  function patch(envelope) {
    if (overlay && envelope && envelope.type === 'state' && envelope.payload) {
      envelope.payload.conversation = overlay.conversation;
      envelope.payload.toolActivities = overlay.toolActivities;
      envelope.payload.streamingMessageId = null;
